INSERT INTO `protocols` (id, name, parameters, bulk_modifier, description, observable, reportable, multiplier, double_params) VALUES
  (1, 'Dump resource', 1, 100, '[R 1 perform]: Dump one unit of resource R into space. Burns 1 fuel.', 1, 1, 0, 0),
  (2, 'Burn power', 1, 100, '[N 2 perform]: Burns N fuel to power the drone''s computer. The engine does this for every drone, 1 fuel per 100,000 instructions; a drone that can''t pay becomes a wreck.', 0, 0, 0, 0),
  (3, 'Wait', 1, 100, '[M 3 perform]: Waits M game minutes (1 to 10,080: a week) doing nothing. The script pauses and runs no instructions until then, so waiting costs no fuel.', 1, 1, 0, 0),
  (7, 'Sell resource', 3, 100, '[P M R 7 perform]: Places order to sell resource R at price P, keeping min M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 0),
  (8, 'Buy resource', 3, 100, '[P M R 8 perform]: Places order to buy resource R at price P, keeping max M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 0),
  (10, 'Push resource', 2, 100, '[N R D 10 perform]: Delivers N units of resource R to drone D. N is required (1 for one unit). It takes one minute of game time. Burns 1 fuel.', -1, -1, 1, 0),
  (11, 'Pull resource', 2, 100, '[N R D 11 perform]: Pulls N units of resource R from drone D. N is required (1 for one unit). It takes one minute of game time. Burns 1 fuel.', -1, -1, 1, 0),
  (12, 'Launch drone', 2, 100, '[D K 12 perform]: Builds a new drone (a clone) from ship kit K in the cargo bay, beside this one, with a copy of drone D''s program and 20 of this drone''s fuel; it runs its launched word. Takes 1 hour plus the light time from D. Burns 30 fuel.', 1, 1, 0, 0),
  (17, 'Sell resource (double price)', 3, 100, '[P M R 17 perform]: Places order to sell resource R at price P, a double (two cells), keeping min M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 4),
  (18, 'Buy resource (double price)', 3, 100, '[P M R 18 perform]: Places order to buy resource R at price P, a double (two cells), keeping max M units at drone''s cargo hold. Burns 1 fuel.', 1, 1, 0, 4),
  (31, 'Offer to station', 2, 100, '[N R 31 perform]: Offers N units of resource R to the House station where the drone is. They leave the hold now; when the hour''s batch clears, the station pays one price for the batch and returns what it doesn''t buy. Burns 1 fuel.', 1, 1, 0, 0),
  (32, 'Order from station', 2, 100, '[N R 32 perform]: Orders N units of resource R from the House station where the drone is. When the hour''s batch clears, the company pays the station''s price for what it gets (as many as its credits and cargo space allow) and the goods arrive.', 1, 1, 0, 0),
  (33, 'Station delivery', 0, 100, 'Goods a House station delivers or returns when a batch clears. Not performed by drones.', 1, 1, 0, 0),
  (34, 'Plunder wreck', 1, 100, '[W 34 perform]: Plunders the wreck W (a drone ID) where the drone is: after 1 hour the drone gets its share of the wreck''s goods and parts, as far as its hold has room; the rest is destroyed. A wreck is plundered once. Burns 1 fuel.', 1, 1, 0, 0),
  (35, 'Plunder haul', 0, 100, 'Goods and parts a plunderer takes from a wreck, and their loss from the wreck. Not performed by drones.', 1, 1, 0, 0),
  (5001, 'Activate Engine I', 0, 100, '[N 5001 perform]: Moves the spacecraft to the the astronimical object whoes Location ID is N. Burns 5 fuel.', 1, 1, 0, 0),
  (5911, 'Import Resource', 1, 100, '[N 5911 perform]: Imports resource N from the planet surface.  Requires an import station. Burns 1 fuel.', 1, 1, 0, 0),
  (5921, 'Export Resource', 1, 100, '[N 5921 perform]: Exports resource N from the cargo bay to the planet surface.  Requires an export station. Burns 1 fuel.', 1, 1, 0, 0),
  (11000, 'Mine magmite', 0, 100, '[11000 perform]: Mine magmite from the planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11010, 'Mine formite', 0, 100, '[11010 perform]: Mine formite from a planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11020, 'Mine voxite', 0, 100, '[11020 perform]: Mine voxite from the surface of a planet, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11030, 'Mine zenolite', 0, 100, '[11030 perform]: Mine zenolite from a planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11100, 'Mine kunspar', 0, 100, '[11100 perform]: Mine kunspar from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11110, 'Mine yalspar', 0, 100, '[11110 perform]: Mine yalspar from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11120, 'Mine vladnium', 0, 100, '[11120 perform]: Mine vladnium from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11130, 'Mine wolfite', 0, 100, '[11130 perform]: Mine wolfite from the surface of a moon, if present. Uses a Worm (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11200, 'Mine kronite', 0, 100, '[11200 perform]: Mine kronite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11210, 'Mine efrite', 0, 100, '[11210 perform]: Mine efrite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11220, 'Mine olivium', 0, 100, '[11220 perform]: Mine olivium from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11230, 'Mine aladanite', 0, 100, '[11230 perform]: Mine aladanite from an asteroid, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11300, 'Mine halosite', 0, 100, '[11300 perform]: Mine halosite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11310, 'Mine stellarite', 0, 100, '[11310 perform]: Mine stellarite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11320, 'Mine mullinite', 0, 100, '[11310 perform]: Mine mullinite from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11330, 'Mine oznium', 0, 100, '[11330 perform]: Mine oznium from a comet, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11400, 'Mine tephnium', 0, 100, '[11400 perform]: Minetephnium from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11410, 'Mine neptine', 0, 100, '[11410 perform]: Mine neptine from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11420, 'Mine empirogen', 0, 100, '[11420 perform]: Mine empirogen from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (11430, 'Mine laudite', 0, 100, '[11430 perform]: Mine laudite from a planetary ring, if present. Uses a Crawler (A1) mining module. Takes 1 hour. Burns 1 fuel.', -1, -1, 0, 0),
  (12021, 'Make Alloys (A1)', 0, 100, '[12021 perform]: Uses 2 Metals (A1) to make 1 Alloys (A1). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12022, 'Make Alloys (A2)', 0, 100, '[12022 perform]: Uses 1 Metals (A1), 1 Metals (A2) to make 1 Alloys (A2). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12023, 'Make Alloys (A3)', 0, 100, '[12023 perform]: Uses 1 Metals (A1), 1 Metals (A2), 1 Metals (A3) to make 2 Alloys (A3). Needs a Smelter (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12042, 'Make Organics (A2)', 0, 100, '[12042 perform]: Uses 1 Inorganics (A2), 2 Organics (A1) to make 2 Organics (A2). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12043, 'Make Organics (A3)', 0, 100, '[12043 perform]: Uses 1 Inorganics (A3), 2 Organics (A2) to make 2 Organics (A3). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12051, 'Make Polymers (A1)', 0, 100, '[12051 perform]: Uses 1 Inorganics (A1), 1 Organics (A1) to make 1 Polymers (A1). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12052, 'Make Polymers (A2)', 0, 100, '[12052 perform]: Uses 1 Inorganics (A1), 1 Organics (A1), 1 Organics (A2) to make 2 Polymers (A2). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12053, 'Make Polymers (A3)', 0, 100, '[12053 perform]: Uses 1 Inorganics (A1), 1 Organics (A2), 1 Organics (A3) to make 2 Polymers (A3). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (12061, 'Make Fuel (A1)', 0, 100, '[12061 perform]: Uses 1 Organics (A1), 2 Inorganics (A1) to make 30 Fuel (A1). Needs a Chemical Reactor (A1); takes 2 hours. Burns 2 fuel.', 1, 1, 0, 0),
  (13001, 'Make Sheets (A1)', 0, 100, '[13001 perform]: Uses 2 Alloys (A1) to make 1 Sheets (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13011, 'Make Rods (A1)', 0, 100, '[13011 perform]: Uses 1 Alloys (A1) to make 1 Rods (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13021, 'Make Cables (A1)', 0, 100, '[13021 perform]: Uses 2 Alloys (A1) to make 1 Cables (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13031, 'Make Fasteners (A1)', 0, 100, '[13031 perform]: Uses 2 Alloys (A2) to make 1 Fasteners (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13101, 'Make Springs (A1)', 0, 100, '[13101 perform]: Uses 2 Alloys (A2) to make 1 Springs (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13111, 'Make Gears (A1)', 0, 100, '[13111 perform]: Uses 2 Alloys (A1) to make 1 Gears (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13121, 'Make Pulleys (A1)', 0, 100, '[13121 perform]: Uses 2 Alloys (A1) to make 1 Pulleys (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13141, 'Make Belts (A1)', 0, 100, '[13141 perform]: Uses 2 Polymers (A1) to make 1 Belts (A1). Needs a Chemical Reactor (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13201, 'Make Conductors (A1)', 0, 100, '[13201 perform]: Uses 2 Alloys (A1) to make 1 Conductors (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13211, 'Make Semiconductors (A1)', 0, 100, '[13211 perform]: Uses 1 Alloys (A2) to make 1 Semiconductors (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13221, 'Make Superconductors (A1)', 0, 100, '[13221 perform]: Uses 2 Alloys (A3) to make 1 Superconductors (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13301, 'Make Hoses (A1)', 0, 100, '[13301 perform]: Uses 3 Polymers (A1) to make 1 Hoses (A1). Needs a Chemical Reactor (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13311, 'Make Pipes (A1)', 0, 100, '[13311 perform]: Uses 3 Alloys (A1) to make 1 Pipes (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13321, 'Make Tanks (A1)', 0, 100, '[13321 perform]: Uses 2 Alloys (A1), 3 Alloys (A2) to make 1 Tanks (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (13331, 'Make Nozzles (A1)', 0, 100, '[13331 perform]: Uses 1 Alloys (A1), 3 Alloys (A2) to make 1 Nozzles (A1). Needs a Smelter (A1); takes 4 hours. Burns 3 fuel.', 1, 1, 0, 0),
  (14101, 'Make Bores (A1)', 0, 100, '[14101 perform]: Uses 1 Rods (A1), 1 Pulleys (A1), 1 Belts (A1) to make 1 Bores (A1). Needs a Spider (A1); takes 8 hours. Burns 4 fuel.', 1, 1, 0, 0),
  (14111, 'Make Gear Boxes (A1)', 0, 100, '[14111 perform]: Uses 1 Rods (A1), 1 Springs (A1), 1 Gears (A1) to make 1 Gear Boxes (A1). Needs a Spider (A1); takes 8 hours. Burns 4 fuel.', 1, 1, 0, 0),
  (14121, 'Make Gyroscopes (A1)', 0, 100, '[14121 perform]: Uses 1 Springs (A1), 1 Gears (A1), 1 Conductors (A1) to make 1 Gyroscopes (A1). Needs a Spider (A1); takes 8 hours. Burns 4 fuel.', 1, 1, 0, 0),
  (14131, 'Make Heat Sinks (A1)', 0, 100, '[14131 perform]: Uses 1 Sheets (A1), 1 Cables (A1), 1 Fasteners (A1) to make 1 Heat Sinks (A1). Needs a Spider (A1); takes 8 hours. Burns 4 fuel.', 1, 1, 0, 0),
  (14141, 'Make Heat Shields (A1)', 0, 100, '[14141 perform]: Uses 2 Sheets (A1), 1 Cables (A1), 1 Fasteners (A1) to make 1 Heat Shields (A1). Needs a Spider (A1); takes 8 hours. Burns 4 fuel.', 1, 1, 0, 0),
