INSERT INTO `queries` (id, name, description, parameters, script) VALUES
  (100, 'Get company name', '[N R L 100 query]: Returns the name for company N.', 1, 'SELECT name FROM companies WHERE company_id = [value_1];'),
  (101, 'Get company credits', '[N R L 101 query]: Returns the number of credits in the company''s bank account were Company ID = N. Money and volumes are double cells (2@).', 1, 'SELECT credits AS d_credits FROM companies WHERE company_id = [value_1];'),
  (110, 'List company spacecraft', '[N R L 110 query]: Returns a list of the IDs for the spacecraft that are owned by company N.', 1, 'SELECT agent_id FROM agents WHERE company_id = [value_1] ORDER BY agent_id;'),
  (200, 'Get spacecraft name', '[N R L 200 query]: Returns the spacecraft name [30] for Spacraft ID N.', 1, 'SELECT agents.name FROM agents WHERE (((agents.agent_id)=[value_1]));'),
  (201, 'Get spacecraft owner', '[N R L 201 query]: Return the Company ID of the compony that owns Spacecraft ID N.', 1, 'SELECT company_id FROM agents WHERE agent_id = [value_1];'),
  (202, 'Get spaecraft location', '[N R L 202 query]: Returns the location ID of spacecraft N.', 1, 'SELECT object_id FROM agents WHERE agent_id = [value_1];'),
  (203, 'Get spacecraft hull type', '[N R L 203 query]: Retuns the hull type of spacecraft N.', 1, 'SELECT hull_type FROM agents WHERE agent_id=[value_1];'),
  (204, 'Get cargo mass', '[N R L 204 query]: Returns the total cargo mass in kg of spacecraft N.', 1, 'SELECT IFNULL(SUM(i.units * r.mass), 0) FROM sqInventory AS i INNER JOIN resources AS r ON r.id = i.resource WHERE i.drone = [value_1];'),
  (205, 'Get my spacecraft ID', '[R L 205 query]: Returns the spacecraft ID of the requesting spacecraft.', 0, 'SELECT agent_id FROM agents WHERE agent_id = [drone_id];'),
  (210, 'List spacecraft inventory', '[N R L 210 query]: Lists the resources and quantities in the cargo hold of spacecraft N.', 1, 'SELECT resource, units FROM sqInventory WHERE drone = [value_1] AND units > 0 ORDER BY units DESC;'),
  (212, 'Get resource quantity', '[N R L 212 query]: Returns how many units of resource N are in the requesting spacecraft''s cargo hold.', 1, 'SELECT IFNULL(MAX(units), 0) FROM sqInventory WHERE drone = [drone_id] AND resource = [value_1];'),
  (300, 'Get hull type name', '[N R L 300 query]: Returns the name of hull type N.', 1, 'SELECT name FROM hulls WHERE id=[value_1];'),
  (301, 'Get hull type cargo capacity', '[N R L 301 query]: Returns the cargo capacity in kg of hull type N.', 1, 'SELECT cargo_capacity FROM hulls WHERE id=[value_1];'),
  (400, 'Get resource name', '[N R L 400 query]: Retuns the name of resource N.', 1, 'SELECT name FROM resources WHERE id=[value_1];'),
  (401, 'Get resource unit mass', '[N R L 401 query]: Retuns the unit mass in kg of resource N.', 1, 'SELECT mass FROM resources WHERE id=[value_1];'),
  (410, 'List best extraction sites', '[N R L 410 query]: Returns the top extraction sites and abundancies for the resource N.', 1, 'SELECT location, multiplier FROM abundancies WHERE resource=[value_1] ORDER BY multiplier DESC;'),
  (500, 'Get protocol name', '[N R L 500 query]: Returns the name of protocol N.', 1, 'SELECT name FROM protocols WHERE id = [value_1];'),
  (501, 'Get protocol duration', '[N R L 501 query]: Returns the duration in minutes of protocol N.', 1, 'SELECT MAX(time) FROM (SELECT time FROM resource_effects WHERE protocol = [value_1] UNION SELECT time FROM market_effects WHERE protocol = [value_1]) AS combined;'),
  (510, 'List consumed resources', '[N R L 510 query]: Lists the resources and quantities that are consumed by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=1 AND locked=0 ORDER BY quantity DESC;'),
  (511, 'List produced resources', '[N R L 511 query]: Lists the resources and quantities that are produced by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=0 ORDER BY quantity DESC;'),
  (512, 'List retained resources', '[N R L 512 query]: Lists the resources and quantities that are used by the protocol but returned when done.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=1 ORDER BY quantity DESC;'),
  (520, 'List consuming protocols', '[N R L 520 query]: Lists all the protocols and qantities that deplete resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 1 AND locked = 0 ORDER BY quantity DESC;'),
  (521, 'List producing protocols', '[N R L 521 query]: Lists all the procedures and quantities that produce resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 0 ORDER BY quantity DESC;'),
  (522, 'List retaining protocols', '[N R L 522 query]: Lists all the protocols and quatities that use resource N without consuming it.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 1 ORDER BY quantity DESC;'),
  (600, 'List local buy orders', '[N R L 600 query]: Lists buy orders for resource N at the requesting spacecraft''s location: price, wanted maximum, units held, spacecraft ID. Money and volumes are double cells (2@).', 1, 'SELECT o.new_credits AS d_price, o.new_quantity, IFNULL(i.units, 0), o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 5 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE IFNULL(i.units, 0) < o.new_quantity ORDER BY o.new_credits DESC;'),
  (601, 'List buy orders here', '[N R L 601 query]: Lists buy orders for resource N where the drone is (like 600): price, wanted maximum, units held, spacecraft ID. Only where the drone is: for elsewhere, see the price board (680). Money and volumes are double cells (2@).', 1, 'SELECT o.new_credits AS d_price, o.new_quantity, IFNULL(i.units, 0), o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 5 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE IFNULL(i.units, 0) < o.new_quantity ORDER BY o.new_credits DESC;'),
  (610, 'List local sell orders', '[N R L 610 query]: Lists sell orders for resource N at the requesting spacecraft''s location: price, kept minimum, units held, spacecraft ID. Money and volumes are double cells (2@).', 1, 'SELECT o.new_credits AS d_price, o.new_quantity, i.units, o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 4 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE i.units > o.new_quantity ORDER BY o.new_credits ASC;'),
  (611, 'List sell orders here', '[N R L 611 query]: Lists sell orders for resource N where the drone is (like 610): price, kept minimum, units held, spacecraft ID. Only where the drone is: for elsewhere, see the price board (680). Money and volumes are double cells (2@).', 1, 'SELECT o.new_credits AS d_price, o.new_quantity, i.units, o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 4 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE i.units > o.new_quantity ORDER BY o.new_credits ASC;'),
  (612, 'Sell orders here up to a price', '[N P R L 612 query]: Sell orders for resource N where the drone is at a price of at most P (a double, e.g. 7 10000 um* for 70,000), cheapest first: price (2 cells), kept minimum, stock, drone.', 3, 'SELECT o.new_credits AS d_price, o.new_quantity, i.units, o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 4 AND resource = [value_3] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_3] WHERE i.units > o.new_quantity AND o.new_credits <= [dvalue_1] ORDER BY o.new_credits ASC;'),
  (620, 'Local market volume', '[N H R L 620 query]: Units of resource N traded at the requesting spacecraft''s location in the last H game hours, credits paid for them, and number of trades. Money and volumes are double cells (2@).', 2, 'SELECT IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_2] AND [game_now]-game_t<=[value_1]*3600 AND location=(SELECT object_id FROM agents WHERE agent_id = [drone_id]);'),
  (621, 'Solar market volume, an hour old', '[N H R L 621 query]: Units of resource N traded anywhere in the solar system in the H game hours up to one game hour ago, credits paid for them, and number of trades. Money and volumes are double cells (2@).', 2, 'SELECT IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_2] AND game_t<=[game_now]-3600 AND [game_now]-3600-game_t<=[value_1]*3600;'),
  (630, 'Station trades here', '[R L 630 query]: What the House station where the drone is trades now: resource, side (1: it buys, 2: it sells), price (2 cells; buying: for an empty batch, halving per daily units), daily units, units waiting in this batch (2 cells).', 0, 'SELECT g.resource, g.side, g.price AS d_price, g.daily_units, IFNULL((SELECT SUM(o.units) FROM station_offers o WHERE o.station_id = g.station_id AND o.resource = g.resource AND o.side = g.side AND o.cleared_t IS NULL), 0) AS d_units FROM station_goods g WHERE g.station_id IN (SELECT id FROM stations WHERE object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id])) AND g.from_day <= FLOOR(([game_now] - (SELECT epoch FROM game_clock WHERE id = 1)) / 86400) ORDER BY g.side, g.resource;'),
  (631, 'My station offers', '[R L 631 query]: This drone''s station offers and orders, newest first: resource, side (1: offer, 2: order), units, units filled (-1 until its batch clears), credits (2 cells).', 0, 'SELECT resource, side, units, IFNULL(filled, -1), IFNULL(paid, 0) AS d_paid FROM station_offers WHERE drone = [drone_id] ORDER BY id DESC;'),
  (632, 'Station budget here', '[R L 632 query]: The credits the House station where the drone is has left for buying (2 cells).', 0, 'SELECT IFNULL(t.budget, s.budget_cap) AS d_budget FROM stations s LEFT JOIN station_state t ON t.station_id = s.id WHERE s.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]);'),
  (640, 'Deposits here', '[R L 640 query]: The mining deposits where the drone is: resource, units left now (2 cells), capacity (2 cells), units regained per game day. A mined-out deposit yields nothing until it refills.', 0, 'SELECT d.resource, FLOOR(LEAST(d.capacity, IFNULL(s.amount, d.capacity) + d.refill_per_day * ([game_now] - IFNULL(s.refilled_t, [game_now])) / 86400)) AS d_units, d.capacity AS d_capacity, d.refill_per_day FROM deposits d LEFT JOIN deposit_state s ON s.object_id = d.object_id AND s.resource = d.resource WHERE d.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) ORDER BY d.resource;'),
  (650, 'My taxes', '[R L 650 query]: The drone''s company''s next tax bill (2 cells), game hours until it is due, and game hours of grace left (no tax until then). A company that can''t pay is eliminated.', 0, 'SELECT h.tax_flat + FLOOR(h.tax_permille * (SELECT IFNULL(w.taxable, 0) FROM company_taxable w WHERE w.company_id = c.company_id) / 1000) AS d_tax, GREATEST(0, CEIL((IFNULL(c.taxed_t, [game_now]) + h.tax_period - [game_now]) / 3600)), GREATEST(0, CEIL((IFNULL(c.founded_t, [game_now]) + h.tax_grace - [game_now]) / 3600)) FROM companies c JOIN house_rules h ON h.id = 1 WHERE c.company_id = (SELECT company_id FROM agents WHERE agent_id = [drone_id]);'),
  (660, 'Wrecks here', '[R L 660 query]: The wrecks where the drone is: drone ID, 1 if it has been plundered (else 0).', 0, 'SELECT agent_id, plundered_at IS NOT NULL FROM agents WHERE wrecked_at IS NOT NULL AND object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND agent_id <> [drone_id] ORDER BY agent_id;'),
  (661, 'Wreck hold', '[W R L 661 query]: What is aboard the wreck W where the drone is: resource, units.', 1, 'SELECT i.resource, i.units FROM sqInventory i JOIN agents w ON w.agent_id = i.drone WHERE i.drone = [value_1] AND w.wrecked_at IS NOT NULL AND w.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) AND i.units > 0 ORDER BY i.resource;'),
  (670, 'My clones', '[R L 670 query]: The drones this drone launched, oldest first: drone ID, 1 if it is a wreck (else 0).', 0, 'SELECT agent_id, wrecked_at IS NOT NULL FROM agents WHERE parent_id = [drone_id] ORDER BY agent_id;'),
  (671, 'My lineage', '[R L 671 query]: The drone that launched this one (0 if none), and its generation (0 for a drone released or registered, 1 for its clones, and so on).', 0, 'SELECT IFNULL(parent_id, 0), generation FROM agents WHERE agent_id = [drone_id];'),
  (680, 'Price board', '[N R L 680 query]: The public price board for resource N: for each place where it traded in the game day up to one game hour ago, the place, units (2 cells), credits paid (2 cells) and trades.', 1, 'SELECT location, IFNULL(SUM(units),0) AS d_units, IFNULL(SUM(credits),0) AS d_credits, COUNT(*) FROM trades WHERE resource=[value_1] AND location IS NOT NULL AND game_t<=[game_now]-3600 AND game_t>[game_now]-3600-86400 GROUP BY location ORDER BY location;'),
  (700, 'Get location name', '[N R L 700 query]: Returns the name of location ID N.', 1, 'SELECT object_name FROM objects WHERE object_id=[value_1];'),
  (701, 'Get location type', '[N R L 701 query]: Returns the location type of location N.', 1, 'SELECT object_type FROM objects WHERE object_id=[value_1];'),
  (702, 'Get central body', '[N R L 702 query]: Retuns the location ID for the body around which N is orbiting.', 1, 'SELECT central_body_object_id FROM objects WHERE object_id=[value_1];'),
  (703, 'Get location coordinates', '[N R L 703 query]: Retuns the x, y, and z coordinates of location N.', 1, 'SELECT objects.x_coord, objects.y_coord, objects.z_coord FROM objects WHERE object_id=[value_1];'),
  (710, 'List orbiting bodies', '[N R L 710 query]: Returns a list of the object IDs that are in orbit around object N.', 1, 'SELECT object_id FROM objects WHERE central_body_object_id=[value_1];'),
  (720, 'List local spacecraft', '[N R L 720 query]: Lists all the drones at location N.', 1, 'SELECT agent_id FROM agents WHERE object_id =[value_1]'),
  (730, 'List local resources', '[N R L 730 query]: Returns the resource ID and abundancy value of each resource that can be recovered from the location.', 1, 'SELECT resource, multiplier FROM abundancies WHERE location=[value_1] ORDER BY multiplier DESC;'),
  (800, 'List personal events', '[N R L 800 query]: Lists the most recent events that affected spacecraft N.', 1, 'SELECT id FROM events WHERE outcome = 1 AND drone = [value_1] ORDER BY game_t DESC, id DESC;'),
  (801, 'List local events', '[R L 801 query]: Lists the most recent events at the requesting spacecraft''s location.', 0, 'SELECT e.id FROM events AS e INNER JOIN agents AS a ON a.agent_id = e.drone WHERE e.outcome = 1 AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) ORDER BY e.game_t DESC, e.id DESC;'),
  (802, 'List solar events', '[R L 802 query]: Lists the most recent events anywhere in the solar system.', 0, 'SELECT id FROM events WHERE outcome = 1 ORDER BY game_t DESC, id DESC;'),
  (803, 'Search observed events', '[A P T M D N X K O R L 803 query]: Lists the events this spacecraft has observed, newest first, that match A P T M D N X K O (see the manual); -1 means any.', 9, 'SELECT e.id FROM events e LEFT JOIN actions a ON a.id=e.action LEFT JOIN agents g ON g.agent_id=e.drone WHERE e.outcome=1 AND (EXISTS(SELECT 1 FROM observations o WHERE o.event=e.id AND o.drone=[drone_id] AND o.game_t<=[game_now]) OR EXISTS(SELECT 1 FROM agents me WHERE me.agent_id=[drone_id] AND e.place=me.object_id AND e.game_t>=me.arrived_t AND e.game_t<=[game_now])) AND ([value_9]<0 OR a.drone=[value_9]) AND ([value_8]<0 OR a.protocol=[value_8]) AND ([value_7]<0 OR e.event_type=[value_7]) AND ([value_6]<0 OR [game_now]-e.game_t>=[value_6]*60) AND ([value_5]<0 OR e.drone=[value_5]) AND ([value_4]<0 OR e.resource=[value_4]) AND ([value_3]<0 OR (e.event_type=2)=([value_3]<>0)) AND ([value_2]<0 OR e.locked=([value_2]<>0)) AND ([value_1]<0 OR g.object_id=[value_1]) ORDER BY e.game_t DESC,e.id DESC;'),
  (810, 'Get event type', '[N R L 810 query]: Get the type ID for event N.', 1, 'SELECT event_type FROM events WHERE outcome=1 AND id=[value_1];'),
  (811, 'Get event type name', '[N R L 811 query]: Returns the name of the type of event N.', 1, 'SELECT t.name FROM events AS e INNER JOIN event_types AS t ON t.id = e.event_type WHERE e.outcome = 1 AND e.id = [value_1];'),
  (820, 'Get acting spacecraft', '[N R L 820 query]: Returns the ID of the spacecraft whose action caused event N.', 1, 'SELECT a.drone FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [value_1];'),
  (821, 'Get associated protocol', '[N R L 821 query]: Returns the ID of the protocol whose action caused event N.', 1, 'SELECT a.protocol FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [value_1];'),
  (831, 'Get affected spacecraft', '[N R L 831 query]: Return the ID of the spacecraft affected by event N.', 1, 'SELECT drone FROM events WHERE outcome=1 AND id=[value_1];'),
  (832, 'Get affected resource', '[N R L 832 query]: Returns the ID of the resource affected by event N.', 1, 'SELECT resource FROM events WHERE outcome = 1 AND id = [value_1];'),
  (840, 'Get new quantity', '[N R L 840 query]: Returns the new quantity set by event N.', 1, 'SELECT new_quantity FROM events WHERE outcome = 1 AND id = [value_1];'),
  (841, 'Get new credits', '[N R L 841 query]: Returns the new credits set by event N. Money and volumes are double cells (2@).', 1, 'SELECT new_credits AS d_credits FROM events WHERE outcome = 1 AND id = [value_1];'),
  (842, 'Get new location', '[N R L 842 query]: Returns the new location set by event N.', 1, 'SELECT new_location FROM events WHERE outcome = 1 AND id = [value_1];'),
  (843, 'Get event time', '[N R L 843 query]: Returns when event N happened: its game day (day 0 is the world''s first) and the even seconds into that day.', 1, 'SELECT FROM_UNIXTIME(game_t) FROM events WHERE outcome = 1 AND id = [value_1];');
